const IMGBASE='https://d2lnr5mha7bycj.cloudfront.net/product-image/file/thumb_';
const normS=x=>x.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/['’`]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const stemW=w=>w.length>3&&w.endsWith('ies')?w.slice(0,-3)+'y':w.length>4&&/(oes|ches|shes|sses|xes)$/.test(w)?w.slice(0,-2):w.length>3&&w.endsWith('s')&&!w.endsWith('ss')?w.slice(0,-1):w;
const MODS=new Set('organic green fresh ripe baby large small whole yellow red sweet white black brown extra virgin natural free range lowfat reduced fat vitamin d 2 1 percent raw'.split(' '));
const SECOND=/\b(candy|chocolate|marshmallow|easter|halloween|christmas|valentine|gumm(y|ies)|peeps|ice cream|yogurt|baby food|cereal|protein|bar|bars|cookie|cookies|muffin|muffins|cake|cakes|pie|chips|snack|snacks|drink|juice|soda|flavored|flavor|puffs|pouch|pouches|bites|smoothie|gelato|sorbet|waffles|bread|pastry|mini)\b/;
let CATI=null;
const U='fl\\.?\\s*oz|oz|ounces?|lbs?|pounds?|kg|g|ml|l|liters?|ct|count|pk|pack|pint|quart|gallon|gal|qt|pt';
const RX=new RegExp('(?:^|[\\s,(])(\\d+(?:\\.\\d+)?)\\s*[- ]?('+U+')\\b','i');
const NORM={ounce:'oz',ounces:'oz',oz:'oz',lb:'lb',lbs:'lb',pound:'lb',pounds:'lb',ct:'ct',count:'ct',pk:'pack',pack:'pack',liter:'L',liters:'L',l:'L',gal:'gal',gallon:'gal',qt:'qt',quart:'qt',pt:'pt',pint:'pt',ml:'mL',kg:'kg',g:'g'};
function itemQty(n){
  const m=n.match(RX);
  if(m){let u=m[2].toLowerCase().replace(/\s+/g,' ').replace('fl.','fl');u=/^fl/.test(u)?'fl oz':(NORM[u]||u);return m[1]+' '+u}
  const w=n.match(/\b(pint|quart|half gallon|gallon)\b/i);return w?w[1][0].toUpperCase()+w[1].slice(1).toLowerCase():'';
}
function catInit(){
  if(CATI)return;
  CATI=window.CATALOG_DATA.map(([n,p,im,a,pr])=>{
    const ws=normS(n).split(' ').map(stemW),hw=normS(n.split(',')[0]).split(' ').map(stemW);
    return {n,p,im,a,pr,q:itemQty(n),ws,hw,str:' '+ws.join(' ')+' ',seg:n.split(',').length,sec:SECOND.test(normS(n))};
  });
}
function catSearch(q,cat,all){
  catInit();
  const qt=normS(q).split(' ').filter(Boolean).map(stemW);if(!qt.length)return [];
  const qs=qt.join(' '),out=[];
  for(const it of CATI){
    if(!(it.p>0))continue;
    if(cat==='Produce'&&!it.pr)continue;
    if(cat&&cat[0]==='~'&&!deptOK(it,cat.slice(1)))continue;
    let sc=0;const last=it.hw[it.hw.length-1];let ok=true;
    for(const t of qt){
      if(it.ws.includes(t))sc+=10;
      else if(t.length>=2&&it.ws.some(w=>w.startsWith(t)))sc+=4;
      else{ok=false;break}
      if(it.hw.includes(t)){sc+=8;if(t===last)sc+=25}
      else if(t.length>=2&&it.hw.some(w=>w.startsWith(t)))sc+=3;
    }
    if(!ok)continue;
    if(it.str.includes(' '+qs+' '))sc+=15;else if(it.str.startsWith(' '+qs))sc+=5;
    sc-=it.hw.filter(w=>!MODS.has(w)&&!qt.includes(w)).length*1.5;
    sc-=(it.seg-1)*1.2;
    if(it.sec&&!qt.some(t=>SECOND.test(t)))sc-=14;
    if(it.im)sc+=6;
    if(it.pr)sc+=100;
    out.push([sc,it]);
  }
  out.sort((a,b)=>b[0]-a[0]||a[1].n.length-b[1].n.length);
  const seen=new Set(),res=[];
  for(const [,it] of out){const k=it.n.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();if(seen.has(k))continue;seen.add(k);res.push(it);if(res.length>=150&&!all)break}
  return res;
}
