function sugKey(t){
  if(t==='miso paste'||t==='miso')return 'miso';
  if(t==='pasta sauce'||t==='marinara sauce')return 'prego';
  if(/(^|\s)(pasta|macaroni|spaghetti|penne|rigatoni|fettuccine|linguine|rotini|farfalle|ziti)$/.test(t)&&!/frozen|sauce|salad|gluten/.test(t))return 'pasta';
  if(/olive oil/.test(t)&&!/vinegar/.test(t))return 'olive oil';
  if(/^(canned|diced|crushed|whole peeled) tomatoes$/.test(t))return 'canned tomatoes';
  if(t==='capers')return 'capers';
  if(/(^|\s)olives$/.test(t)&&!/canned|bar/.test(t))return 'olives';
  if(/^(vinegar|white vinegar|apple cider vinegar|red wine vinegar|rice vinegar|balsamic vinegar)$/.test(t))return 'vinegar';
  if(/bread ?crumbs/.test(t))return 'breadcrumbs';
  if(/parmesan/.test(t))return 'parmesan cheese';
  return '';
}
