function sugImg(k){if(SIMG[k])return SIMG[k];const t=document.querySelector('.pt[data-q="'+k+'"] img');return t?t.src:''}
function shSugg(){
  const q=S.q.trim().toLowerCase(),dev=$('#device');
  if(S.cat){dev.classList.remove('sg');shCardsSync();return}
  $('#shCards').hidden=true;
  const on=!!q&&!$('#kb').classList.contains('hide');
  dev.classList.toggle('sg',on);if(!on)return;
  const find=(t,w)=>{let p=0;while((p=t.indexOf(w,p))>=0){if(p===0||t[p-1]===' ')return p;p++}return -1};
  let hits=[];
  SUG.forEach(([t,k],i)=>{const at=find(t,q);if(at>=0)hits.push({t,k,at,i,n:q.length})});
  hits.sort((a,b)=>(a.at?1:0)-(b.at?1:0)||a.i-b.i);
  if(hits.length<4&&q.length>=5){const w=q.slice(0,-1);SUG.forEach(([t,k],i)=>{if(hits.some(h=>h.t===t))return;const at=find(t,w);if(at>=0)hits.push({t,k,at,i,n:w.length})})}
  const rows=hits.slice(0,4).map(h=>`<button class="sr" data-act="sugg" data-q="${h.t}"><span class="si">${sugImg(h.k)?`<img src="${sugImg(h.k)}" alt="">`:'<i class="gph"></i>'}</span><span class="st">${h.t.slice(0,h.at)}<b>${h.t.slice(h.at,h.at+h.n)}</b>${h.t.slice(h.at+h.n)}</span>${SSI}</button>`);
  if(!rows.length)rows.push(`<button class="sr" data-act="sugg" data-q="${S.q.trim()}"><span class="si"><i class="gph"></i></span><span class="st"><b>${S.q.trim()}</b></span>${SSI}</button>`);
  $('#shSugg').innerHTML=rows.join('');
}
